-- ═══════════════════════════════════════════════════════════════════════════
-- Horizon COMPASS — UDOT conference demo dataset
--
-- Two realistic Utah public-involvement projects with full supporting data,
-- built for a live demo of the desktop app and the PI Client Portal.
--
--   A. SR-154 Corridor Safety Improvements  (25-154-001, UDOT Region 2)
--      Environmental Assessment, EA - Draft stage, Salt Lake County.
--   B. Logan City 400 North Reconstruction  (25-LC-400N, Logan City Engineering)
--      Categorical Exclusion, Post-NEPA / Construction, Cache County.
--
-- HOW TO RUN
--   Paste the whole file into the Supabase SQL Editor and run it once.
--
-- IDEMPOTENT
--   Re-running deletes everything this script previously created (matched on
--   project number) and rebuilds it. Nothing outside these two projects is
--   touched. Stakeholders are only deleted if they are not linked to any other
--   project.
--
-- RE-RUN BEFORE THE DEMO
--   The most recent eight weeks of interactions are dated RELATIVE to
--   current_date, so the portal's "Engagement Activity — Last 8 Weeks" chart is
--   always full no matter when the demo happens. Everything older uses fixed
--   dates tied to the real project milestones. Re-run this script the week of
--   the conference to refresh that window.
--
-- STAFF INITIALS
--   logged_by is seeded as PUT / SHA / SAV, matching what getLoggedBy() stamps
--   from the login email (putzke@ -> PUT). Seeding full names instead would
--   leave none of the demo data owned by the signed-in user, so the follow-up
--   "Assigned to me" filter and the dashboard card would both read zero.
--
-- ALL ORGANIZATIONS ARE REAL UTAH ENTITIES; ALL INDIVIDUALS ARE FICTIONAL.
--   Emails use non-routable demo domains so nothing can be sent to a real
--   person by accident.
--
-- SEE ALSO
--   The optional block at the very bottom converts Project A from EA to a full
--   EIS (DEIS stage, 45-day comment period) if you would rather demo the EIS
--   colour of the portal's NEPA banner.
-- ═══════════════════════════════════════════════════════════════════════════

begin;

-- ── 0. Slug → generated-id maps (temporary, dropped at the end) ─────────────
drop table if exists _seed_proj;
drop table if exists _seed_stake;
create temporary table _seed_proj  (slug text primary key, id bigint not null);
create temporary table _seed_stake (slug text primary key, id bigint not null);


-- ═══════════════════════════════════════════════════════════════════════════
-- 1. PURGE any previous run of this seed
-- ═══════════════════════════════════════════════════════════════════════════
do $$
declare
  demo_pids text[] := array['25-154-001','25-LC-400N','25-3W-DESIGN'];
  ids text[];          -- TEXT, not bigint: project_id is text on some of these
  demo_stakes text[];  -- tables and bigint on others. Comparing as text works
                       -- for both, the same way the RLS policies in
                       -- sql/2026-07-04_portal_links.sql do.
begin
  select coalesce(array_agg(id::text), '{}'::text[]) into ids
    from pi_projects where pid = any(demo_pids);
  if coalesce(array_length(ids, 1), 0) = 0 then
    raise notice 'No previous demo projects found — nothing to purge.';
    return;
  end if;

  delete from pi_issue_interactions
   where interaction_id::text in (select id::text from pi_interactions
                                   where project_id::text = any(ids));
  delete from pi_interactions        where project_id::text = any(ids);
  delete from pi_public_comments     where project_id::text = any(ids);
  delete from pi_comment_periods     where project_id::text = any(ids);
  delete from pi_commitments         where project_id::text = any(ids);
  delete from pi_deliverables        where project_id::text = any(ids);
  delete from pi_meetings            where project_id::text = any(ids);
  delete from pi_issues              where project_id::text = any(ids);
  delete from pi_tribal_consultations where project_id::text = any(ids);
  delete from pi_group_members
   where group_id::text in (select id::text from pi_groups
                             where project_id::text = any(ids));
  delete from pi_groups              where project_id::text = any(ids);
  delete from pi_parcel_owners
   where parcel_id::text in (select id::text from pi_parcels
                              where project_id::text = any(ids));
  delete from pi_parcels             where project_id::text = any(ids);
  delete from pi_reports             where project_id::text = any(ids);
  delete from pi_report_archive      where project_id::text = any(ids);
  delete from pi_client_summaries    where project_id::text = any(ids);
  delete from pi_portal_links        where project_id::text = any(ids);
  delete from pi_client_access       where project_id::text = any(ids);

  -- Stakeholders that belong ONLY to the demo projects. A contact that has
  -- since been linked to a real project is left alone. The ids are captured
  -- BEFORE the link rows are deleted, because the link rows are what identify
  -- them — and they are deleted AFTER, because of the foreign key.
  select coalesce(array_agg(s.id::text), '{}'::text[]) into demo_stakes
    from pi_stakeholders s
   where s.id::text in (select stakeholder_id::text from pi_project_stakeholders
                         where project_id::text = any(ids))
     and not exists (
       select 1 from pi_project_stakeholders ps
        where ps.stakeholder_id::text = s.id::text
          and not (ps.project_id::text = any(ids)));

  delete from pi_project_stakeholders where project_id::text = any(ids);
  delete from pi_group_members where stakeholder_id::text = any(demo_stakes);
  delete from pi_stakeholders  where id::text        = any(demo_stakes);
  delete from pi_projects             where id::text = any(ids);
  raise notice 'Purged % previous demo project(s) and % demo-only stakeholder(s).',
    array_length(ids, 1), coalesce(array_length(demo_stakes, 1), 0);
end $$;


-- ═══════════════════════════════════════════════════════════════════════════
-- 2. PROJECTS
-- ═══════════════════════════════════════════════════════════════════════════
do $$
declare r record; nid bigint;
begin
  for r in select * from (values
    ('sr154','25-154-001','SR-154 Corridor Safety Improvements','UDOT Region 2','Roadway','Salt Lake','NEPA / Environmental','Active','2024-03-04','2026-12-18','EA','EA - Draft','SR-154 (Bangerter Highway) corridor safety and operational improvements between 11400 South and the Point of the Mountain, Salt Lake County. Environmental Assessment under UDOT NEPA assignment (23 USC 327). PI Lead: Jeff Putzke. Support: Shaylie Bryner, Savannah Hansen.'),
    ('logan','25-LC-400N','Logan City 400 North Reconstruction','Logan City Engineering','Roadway','Cache','Construction','Active','2025-01-13','2026-10-30','CE','Post-NEPA / Construction','Full-depth reconstruction of 400 North in Logan City (Cache County) from Main Street east to 800 East, including water and sewer replacement, new curb, gutter, sidewalk and a school-zone crossing upgrade at Ellis Elementary. Categorical Exclusion cleared; project is in active construction. PI Lead: Jeff Putzke. Support: Shaylie Bryner, Savannah Hansen.')
    ,('west3','25-3W-DESIGN','3600 West Corridor Widening','Weber County Engineering','Roadway','Weber','Design','Active','2026-02-02','2028-06-30','CE','Post-NEPA / Design','Widening of 3600 West from 1200 South to 2700 South in Weber County to a three-lane section with a centre turn lane, curb, gutter and a detached walk on the east side. Categorical Exclusion cleared; project is in final design with right-of-way acquisition under way. Seven parcels are affected, most partial takes for the walk and drainage. PI Lead: Jeff Putzke. Support: Shaylie Bryner.')
  ) as v(slug,pid,name,client,project_type,county,phase,status,start_date,end_date,
         nepa_classification,nepa_stage,notes)
  loop
    insert into pi_projects
      (pid,name,client,project_type,county,phase,status,start_date,end_date,
       nepa_classification,nepa_stage,notes,phase_history,nepa_stage_history)
    values
      (r.pid,r.name,r.client,r.project_type,r.county,r.phase,r.status,
       r.start_date::date,r.end_date::date,r.nepa_classification,r.nepa_stage,
       r.notes,'[]'::jsonb,'[]'::jsonb)
    returning id into nid;
    insert into _seed_proj values (r.slug, nid);
  end loop;
end $$;

-- NEPA PI checklists (drives the checklist progress bar on the desktop
-- dashboard and project cards). Keys match NEPA_CHECKLISTS in index.html.
update pi_projects set nepa_checklist = '[{"key": "EA-01", "group": "NEPA Disclosure", "label": "NEPA assignment disclosure statement included in all NOI, scoping notices, and PI materials: \"The environmental review, consultation, and other actions required by applicable Federal environmental laws for this project are being or have been carried out by UDOT pursuant to 23 USC 327 and a Memorandum of Understanding dated May 26, 2022, and executed by FHWA and UDOT.\"", "checked": true, "checkedDate": "2024-03-18", "checkedBy": "J. Putzke"}, {"key": "EA-02", "group": "PI Planning", "label": "Public information from project sponsor reviewed by PI team (Task 01E)", "checked": true, "checkedDate": "2024-04-05", "checkedBy": "J. Putzke"}, {"key": "EA-03", "group": "PI Planning", "label": "Project stakeholders identified in coordination with Project Manager, RCM, and Communications Office", "checked": true, "checkedDate": "2024-04-23", "checkedBy": "J. Putzke"}, {"key": "EA-04", "group": "PI Planning", "label": "PI strategy meeting held with project team \u2014 PI goals and evaluation criteria established", "checked": true, "checkedDate": "2024-05-11", "checkedBy": "J. Putzke"}, {"key": "EA-05", "group": "PI Planning", "label": "Community outreach strategies developed to meet PI Plan objectives", "checked": true, "checkedDate": "2024-05-29", "checkedBy": "J. Putzke"}, {"key": "EA-06", "group": "PI Planning", "label": "Media plan developed with RCM and Communications Office", "checked": true, "checkedDate": "2024-06-17", "checkedBy": "J. Putzke"}, {"key": "EA-07", "group": "PI Planning", "label": "Project Public Involvement (PI) Plan prepared (Task 05E)", "checked": true, "checkedDate": "2024-07-05", "checkedBy": "J. Putzke"}, {"key": "EA-08", "group": "PI Planning", "label": "PI Plan reviewed and approved by Environmental Program Manager and RCM before distribution", "checked": true, "checkedDate": "2024-07-23", "checkedBy": "J. Putzke"}, {"key": "EA-09", "group": "PI Plan Implementation", "label": "PI Plan implemented throughout planning and design process (Task 07E)", "checked": true, "checkedDate": "2024-08-10", "checkedBy": "J. Putzke"}, {"key": "EA-10", "group": "Scoping & Agency Coordination", "label": "All interested agencies, communities, special-interest groups, and other stakeholders contacted and advised of project scope; comments and recommendations solicited (Task 13E)", "checked": true, "checkedDate": "2024-08-29", "checkedBy": "J. Putzke"}, {"key": "EA-11", "group": "Scoping & Agency Coordination", "label": "NEPA scoping letters sent to agencies, tribes, and known interested parties", "checked": true, "checkedDate": "2024-09-16", "checkedBy": "J. Putzke"}, {"key": "EA-12", "group": "Scoping & Agency Coordination", "label": "Official written notification sent to tribal chairpersons of federally-recognized Indian Tribes in Utah for projects with potential tribal implications (UDOT 08A2-07)", "checked": true, "checkedDate": "2024-10-04", "checkedBy": "J. Putzke"}, {"key": "EA-13", "group": "Scoping & Agency Coordination", "label": "Tribal consultation initiated as early as possible and conducted in good faith; technical information shared with Tribes upon request (UDOT 08A2-07 / Utah EO 2014/005)", "checked": true, "checkedDate": "2024-10-22", "checkedBy": "J. Putzke"}, {"key": "EA-14", "group": "Scoping & Agency Coordination", "label": "NEPA scoping meeting(s) held \u2014 public and agency input solicited", "checked": true, "checkedDate": "2024-11-10", "checkedBy": "J. Putzke"}, {"key": "EA-15", "group": "Scoping & Agency Coordination", "label": "Tribal comments and concerns documented and considered; consultation activities retained in project file", "checked": true, "checkedDate": "2024-11-28", "checkedBy": "J. Putzke"}, {"key": "EA-16", "group": "Scoping & Agency Coordination", "label": "NEPA scoping report prepared", "checked": true, "checkedDate": "2024-12-16", "checkedBy": "J. Putzke"}, {"key": "EA-17", "group": "EA Preparation", "label": "EA submitted to Central Environmental for review and approval BEFORE the public hearing \u2014 EA does not need to be formally circulated for comment (UDOT MOI Ch. 4.5(B)(2))", "checked": true, "checkedDate": "2025-01-03", "checkedBy": "J. Putzke"}, {"key": "EA-18", "group": "Hearing Assessment", "label": "Public hearing requirement assessed \u2014 required when project requires substantial amounts of right-of-way; substantially changes the layout or function of connecting roads or of the facility being improved; has a substantial adverse impact on abutting property; OR UDOT determines hearing is in the public interest (23 CFR 771.111(h)(2)(iii); UDOT MOI Ch. 4.5(B)(2)); both in-person and virtual hearing formats encouraged", "checked": true, "checkedDate": "2025-01-22", "checkedBy": "J. Putzke"}, {"key": "EA-19", "group": "Notice of Availability", "label": "Notice of Availability (NOA) issued in local, state, or regional clearinghouses, newspapers, and other means \u2014 EA must be made available for public review at UDOT Region office (UDOT MOI Ch. 4.5(B)(2))", "checked": true, "checkedDate": "2025-02-09", "checkedBy": "J. Putzke"}, {"key": "EA-20", "group": "Public Hearing Advertisement", "label": "TWO newspaper notices published in statewide and local newspapers \u2014 first notice \u226515 days before request-for-hearing deadline; second notice \u22657 days before deadline; deadline stated as postmark deadline (UDOT MOI Ch. 4.5(A)(4)(a))", "checked": true, "checkedDate": "2025-02-27", "checkedBy": "J. Putzke"}, {"key": "EA-21", "group": "Public Hearing Advertisement", "label": "Written notice sent to all county commissioners, mayors, city council members, state legislators, multi-county planning districts, and all federal/state/local government offices with interest in the project (UDOT MOI Ch. 4.5(A)(5))", "checked": true, "checkedDate": "2025-03-17", "checkedBy": "J. Putzke"}, {"key": "EA-22", "group": "Public Hearing Logistics", "label": "Public hearing location selected: in project area, ADA-accessible, adequate size, accessible working elevator if stairs are required to reach meeting room (Task 39E)", "checked": true, "checkedDate": "2025-04-04", "checkedBy": "J. Putzke"}, {"key": "EA-23", "group": "Public Hearing Logistics", "label": "Public hearing approval obtained from Environmental Program Manager", "checked": true, "checkedDate": "2025-04-23", "checkedBy": "J. Putzke"}, {"key": "EA-24", "group": "Public Hearing Logistics", "label": "Signage at venue must be big enough to be readable", "checked": true, "checkedDate": "2025-05-11", "checkedBy": "J. Putzke"}, {"key": "EA-25", "group": "Public Hearing Logistics", "label": "Public hearing advertised on UDOT website under Public Meetings and Events using the UDOT Publish Public Meeting Form (connect.udot.utah.gov/public/public-meetings/)", "checked": true, "checkedDate": "2025-05-29", "checkedBy": "J. Putzke"}, {"key": "EA-26", "group": "Public Hearing Logistics", "label": "Title VI Coordinator invited to public hearing \u2014 Harley McCall at civilrights@utah.gov", "checked": true, "checkedDate": "2025-06-16", "checkedBy": "J. Putzke"}, {"key": "EA-27", "group": "Public Hearing Logistics", "label": "Community demographics reviewed \u2014 interpreter or translator provided if needed; UDOT Title VI Program home page translator resource list consulted (connect.udot.utah.gov/business/civil-rights/); interpretation services advertised in all flyers and notices", "checked": true, "checkedDate": "2025-07-05", "checkedBy": "J. Putzke"}, {"key": "EA-28", "group": "Public Hearing Logistics", "label": "If demographics indicate need: hearing advertised to minority publications and relevant state cultural affairs offices \u2014 Office of Latino Affairs, Office on Asian & Pacific Islander Affairs, Office on African Affairs, Office of Indian Affairs, Office of Refugee Services, Office of Veteran Affairs, Office of Disability Rights, Office of Aging, and Senior Centers", "checked": true, "checkedDate": "2025-07-23", "checkedBy": "J. Putzke"}, {"key": "EA-29", "group": "Public Hearing Logistics", "label": "Meeting collateral includes Notice of Special Accommodation statement \u2014 project team name, phone, and email filled into the blank: \"Any individual needing special accommodations (including auxiliary communicative aids and services) during this meeting should contact the project team at: ___\"", "checked": true, "checkedDate": "2025-08-10", "checkedBy": "J. Putzke"}, {"key": "EA-30", "group": "Public Hearing Logistics", "label": "Non-discrimination poster obtained from UDOT Title VI Program home page and displayed at public hearing venue (connect.udot.utah.gov/business/civil-rights/)", "checked": true, "checkedDate": "2025-08-28", "checkedBy": "J. Putzke"}, {"key": "EA-31", "group": "Public Hearing Logistics", "label": "Title VI-approved sign-in sheet (from UDOT Title VI Program home page) at each table \u2014 includes option to mark race, sex, and disability; also captures name/affiliation, contact info, and project info opt-in (23 CFR \u00a7200.9(4))", "checked": true, "checkedDate": "2025-09-16", "checkedBy": "J. Putzke"}, {"key": "EA-32", "group": "Public Hearing Logistics", "label": "Comment collection method provided at public hearing", "checked": true, "checkedDate": "2025-10-04", "checkedBy": "J. Putzke"}, {"key": "EA-33", "group": "Public Hearing Logistics", "label": "Court recorder present to record attendee comments at public hearing", "checked": true, "checkedDate": "2025-10-22", "checkedBy": "J. Putzke"}, {"key": "EA-34", "group": "Public Hearing Logistics", "label": "Public hearing held \u2014 compliant with UDOT Title VI Program (non-discrimination: race, color, national origin, sex, age, disability, income status)", "checked": true, "checkedDate": "2025-11-09", "checkedBy": "J. Putzke"}, {"key": "EA-35", "group": "Public Hearing Logistics", "label": "Scanned sign-in sheets and copies of all comments emailed to Title VI Coordinator at civilrights@utah.gov immediately after hearing", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-36", "group": "Public Hearing Logistics", "label": "Post-meeting Civil Rights and Title VI Summary form completed and submitted to civilrights@utah.gov \u2014 form must include: meeting title, date/time, venue name and address; names of all project team members in attendance; summary of event including purpose, pertinent questions and comments, and action items related to Title VI Protected Populations; advertising methods used with collateral attached; confirmation that Notice of Special Accommodations appeared in ads and how many days in advance; accommodations actually provided (audio, visual, technology, sign language, ADA, age-related \u2014 with counts); language translation services (languages provided and number of individuals served); attendee demographic breakdown (race/ethnicity, gender, disability)", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-37", "group": "Public Hearing Logistics", "label": "Public hearing transcript prepared and distributed to project team, interested individuals, groups, and agencies (UDOT 08A2-02)", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-38", "group": "Comment Period", "label": "EA public comment period completed \u2014 minimum 30 days; comment period begins day of first advertisement; start and end dates documented (UDOT MOI Ch. 4.5(A)(10); Task 39E)", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-39", "group": "Comment Resolution", "label": "All public and agency comments compiled into comment resolution form (Task 41E)", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-40", "group": "Comment Resolution", "label": "Written response prepared for each comment received", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-41", "group": "Comment Resolution", "label": "Public hearing certification package assembled (Task 41E)", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-42", "group": "Comment Resolution", "label": "Public hearing summary and analysis report prepared and QC reviewed", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-43", "group": "Comment Resolution", "label": "Environmental document revised per comment responses", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-44", "group": "FONSI & Decision", "label": "Finalized EA, public hearing transcript, all comments, and responses to comments submitted to Central Environmental with recommendation for proposed action (if no significant impacts identified)", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-45", "group": "FONSI & Decision", "label": "FONSI or EIS determination made by Central Environmental \u2014 if FONSI, separate written FONSI prepared incorporating EA by reference", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-46", "group": "FONSI & Decision", "label": "If project would normally require EIS: final EA made available for public review minimum 30 days before FONSI issuance (23 CFR 771.119; UDOT MOI Ch. 4.5(B)(2)(a))", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-47", "group": "FONSI & Decision", "label": "NOA of FONSI issued per 23 CFR 771.121 \u2014 sent to affected federal/state/local government units and state intergovernmental review contacts established under Executive Order 12372; document available from UDOT on public request", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-48", "group": "Title VI", "label": "Non-discrimination compliance confirmed \u2014 race, color, national origin (Title VI / 42 USC 2000d), sex (23 USC 324), age (Age Discrimination Act), disability (ADA / Section 504), income status, gender identity, sexual orientation", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "EA-49", "group": "Documentation & Closeout", "label": "Project PI file assembled and maintained (Task 55E)", "checked": false, "checkedDate": "", "checkedBy": ""}]'::jsonb
 where id = (select id from _seed_proj where slug = 'sr154');
update pi_projects set nepa_checklist = '[{"key": "CE-01", "group": "NEPA Disclosure", "label": "NEPA assignment disclosure statement included in all NOI, scoping notices, and PI materials: \"The environmental review, consultation, and other actions required by applicable Federal environmental laws for this project are being or have been carried out by UDOT pursuant to 23 USC 327 and a Memorandum of Understanding dated May 26, 2022, and executed by FHWA and UDOT.\"", "checked": true, "checkedDate": "2025-01-20", "checkedBy": "J. Putzke"}, {"key": "CE-02", "group": "Hearing Assessment", "label": "Public hearing requirement assessed and documented \u2014 required if project is on a new location; substantially changes the layout or function of connecting roads or of the facility being improved; has a substantially different social, economic, or environmental effect than the existing facility; has a substantial adverse impact on abutting property; OR UDOT determines a hearing is in the public interest (23 CFR 771.111(h)(2)(iii); UDOT MOI Ch. 4.5(B)(1))", "checked": true, "checkedDate": "2025-02-10", "checkedBy": "J. Putzke"}, {"key": "CE-03", "group": "Agency & Stakeholder Coordination", "label": "All interested agencies, communities, special-interest groups, and other stakeholders contacted and advised of project scope", "checked": true, "checkedDate": "2025-03-03", "checkedBy": "J. Putzke"}, {"key": "CE-04", "group": "Agency & Stakeholder Coordination", "label": "Comments and recommendations solicited from all stakeholders; continued stakeholder involvement maintained throughout decision-making process", "checked": true, "checkedDate": "2025-03-25", "checkedBy": "J. Putzke"}, {"key": "CE-05", "group": "CE Document", "label": "CE Environmental Study made available for public review at applicant''s office (and additional locations as decided by project team) \u2014 CE document does not need to be formally circulated for comment (UDOT MOI Ch. 4.5(B)(1))", "checked": true, "checkedDate": "2025-04-15", "checkedBy": "J. Putzke"}, {"key": "CE-06", "group": "If Public Hearing Held", "label": "If public hearing held: TWO newspaper notices published in statewide and local newspapers \u2014 first notice published \u226515 days before request-for-hearing deadline; second notice published \u22657 days before deadline; deadline stated as postmark deadline (UDOT MOI Ch. 4.5(A)(4)(a))", "checked": true, "checkedDate": "2025-05-06", "checkedBy": "J. Putzke"}, {"key": "CE-07", "group": "If Public Hearing Held", "label": "If public hearing held: written notice sent to all county commissioners, mayors, city council members, state legislators, multi-county planning districts, and all federal/state/local government offices with interest in the project (UDOT MOI Ch. 4.5(A)(5))", "checked": true, "checkedDate": "2025-05-28", "checkedBy": "J. Putzke"}, {"key": "CE-08", "group": "If Public Hearing Held", "label": "If public hearing held: hearing location in project area \u2014 ADA-accessible, adequate size, accessible working elevator if stairs are required to reach meeting room", "checked": true, "checkedDate": "2025-06-18", "checkedBy": "J. Putzke"}, {"key": "CE-09", "group": "If Public Hearing Held", "label": "If public hearing held: signage at venue must be big enough to be readable", "checked": true, "checkedDate": "2025-07-10", "checkedBy": "J. Putzke"}, {"key": "CE-10", "group": "If Public Hearing Held", "label": "If public hearing held: advertised on UDOT website under Public Meetings and Events using the UDOT Publish Public Meeting Form (connect.udot.utah.gov/public/public-meetings/)", "checked": true, "checkedDate": "2025-07-31", "checkedBy": "J. Putzke"}, {"key": "CE-11", "group": "If Public Hearing Held", "label": "If public hearing held: Title VI Coordinator invited to meeting \u2014 Harley McCall at civilrights@utah.gov", "checked": true, "checkedDate": "2025-08-21", "checkedBy": "J. Putzke"}, {"key": "CE-12", "group": "If Public Hearing Held", "label": "If public hearing held: community demographics reviewed \u2014 interpreter or translator provided if needed; UDOT Title VI Program home page translator resource list consulted (connect.udot.utah.gov/business/civil-rights/); interpretation services advertised in all flyers and notices", "checked": true, "checkedDate": "2025-09-12", "checkedBy": "J. Putzke"}, {"key": "CE-13", "group": "If Public Hearing Held", "label": "If demographics indicate need: hearing/event advertised to minority publications and relevant state cultural affairs offices \u2014 Office of Latino Affairs, Office on Asian & Pacific Islander Affairs, Office on African Affairs, Office of Indian Affairs, Office of Refugee Services, Office of Veteran Affairs, Office of Disability Rights, Office of Aging, and Senior Centers", "checked": true, "checkedDate": "2025-10-03", "checkedBy": "J. Putzke"}, {"key": "CE-14", "group": "If Public Hearing Held", "label": "If public hearing held: meeting collateral includes Notice of Special Accommodation statement \u2014 project team name, phone, and email must be filled into the blank: \"Any individual needing special accommodations (including auxiliary communicative aids and services) during this meeting should contact the project team at: ___\"", "checked": true, "checkedDate": "2025-10-24", "checkedBy": "J. Putzke"}, {"key": "CE-15", "group": "If Public Hearing Held", "label": "If public hearing held: non-discrimination poster obtained from UDOT Title VI Program home page and displayed at venue (connect.udot.utah.gov/business/civil-rights/)", "checked": true, "checkedDate": "2025-11-15", "checkedBy": "J. Putzke"}, {"key": "CE-16", "group": "If Public Hearing Held", "label": "If public hearing held: Title VI-approved sign-in sheet (from UDOT Title VI Program home page) at each table \u2014 includes option to mark race, sex, and disability; also captures name/affiliation, contact info, and project info opt-in (23 CFR \u00a7200.9(4))", "checked": true, "checkedDate": "2025-12-06", "checkedBy": "J. Putzke"}, {"key": "CE-17", "group": "If Public Hearing Held", "label": "If public hearing held: comment collection method provided at hearing", "checked": true, "checkedDate": "2025-12-28", "checkedBy": "J. Putzke"}, {"key": "CE-18", "group": "If Public Hearing Held", "label": "If public hearing held: court recorder present to record attendee comments", "checked": true, "checkedDate": "2026-01-18", "checkedBy": "J. Putzke"}, {"key": "CE-19", "group": "If Public Hearing Held", "label": "If public hearing held: scanned sign-in sheets and copies of all comments emailed to Title VI Coordinator at civilrights@utah.gov immediately after hearing", "checked": true, "checkedDate": "2026-02-08", "checkedBy": "J. Putzke"}, {"key": "CE-20", "group": "If Public Hearing Held", "label": "If public hearing held: post-meeting Civil Rights and Title VI Summary form completed and submitted to civilrights@utah.gov \u2014 form must include: meeting title, date/time, venue name and address; names of all project team members in attendance; summary of event including purpose, pertinent questions and comments, and action items related to Title VI Protected Populations; advertising methods used with collateral attached; confirmation that Notice of Special Accommodations appeared in ads and how many days in advance; accommodations actually provided (audio, visual, technology, sign language, ADA, age-related \u2014 with counts); language translation services (languages provided and number of individuals served); attendee demographic breakdown (race/ethnicity, gender, disability)", "checked": true, "checkedDate": "2026-03-02", "checkedBy": "J. Putzke"}, {"key": "CE-21", "group": "If Public Hearing Held", "label": "If public hearing held: comment period minimum 10 days following the hearing; if day 10 falls on a Sunday or holiday, extended one additional day \u2014 comment period start/end dates documented (UDOT MOI Ch. 4.5(A)(10))", "checked": true, "checkedDate": "2026-03-23", "checkedBy": "J. Putzke"}, {"key": "CE-22", "group": "If Public Hearing Held", "label": "If public hearing held: public hearing transcript prepared and certification attached to CE document; transcript distributed per UDOT 08A2-02", "checked": true, "checkedDate": "2026-04-13", "checkedBy": "J. Putzke"}, {"key": "CE-23", "group": "If Public Hearing Held", "label": "If public hearing held: all comments and responses summarized and included in CE document", "checked": true, "checkedDate": "2026-05-05", "checkedBy": "J. Putzke"}, {"key": "CE-24", "group": "Noise Barrier", "label": "If noise impacts identified: noise barrier eligibility and reasonableness determination documented", "checked": true, "checkedDate": "2026-05-26", "checkedBy": "J. Putzke"}, {"key": "CE-25", "group": "Noise Barrier", "label": "If noise ballot required: affected property owners and tenants notified by mail with return deadline of at least 30 days; 75% favorable return rate required before barrier is included in project; ballot results documented in project file", "checked": true, "checkedDate": "2026-06-17", "checkedBy": "J. Putzke"}, {"key": "CE-26", "group": "Title VI", "label": "Non-discrimination compliance confirmed \u2014 race, color, national origin (Title VI / 42 USC 2000d), sex (23 USC 324), age (Age Discrimination Act), disability (ADA / Section 504), income status, gender identity, sexual orientation", "checked": true, "checkedDate": "2026-07-08", "checkedBy": "J. Putzke"}, {"key": "CE-27", "group": "Tribal Consultation", "label": "Project assessed for tribal implications \u2014 cultural practices, lands, resources, traditional/religious areas (UDOT 08A2-07; Utah Executive Order 2014/005)", "checked": true, "checkedDate": "2026-07-29", "checkedBy": "J. Putzke"}, {"key": "CE-28", "group": "Tribal Consultation", "label": "If tribal implications identified: official written notification sent to tribal chairpersons of all federally-recognized Indian Tribes located wholly or partially in Utah", "checked": true, "checkedDate": "2026-08-20", "checkedBy": "J. Putzke"}, {"key": "CE-29", "group": "Tribal Consultation", "label": "If tribal consultation required: initiated as early as possible; conducted in good faith; technical information and data shared with Tribes upon request", "checked": true, "checkedDate": "2026-09-10", "checkedBy": "J. Putzke"}, {"key": "CE-30", "group": "Tribal Consultation", "label": "If tribal consultation conducted: tribal comments and concerns documented and considered in project decisions; all consultation activities retained in project file", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "CE-31", "group": "Documentation & Closeout", "label": "All public involvement activities documented with supporting information in project file", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "CE-32", "group": "Documentation & Closeout", "label": "Environmental Commitments Signature Page signed and included in CE document", "checked": false, "checkedDate": "", "checkedBy": ""}, {"key": "CE-33", "group": "Documentation & Closeout", "label": "Mitigation commitments entered in ePM and included in project file", "checked": false, "checkedDate": "", "checkedBy": ""}]'::jsonb
 where id = (select id from _seed_proj where slug = 'logan');


