-- 4. PROJECT ↔ STAKEHOLDER LINKS
--    distribution_groups values must match DIST_GROUPS in index.html exactly
--    ('Project team', 'Agency contacts', 'Media', 'Other') — report
--    distribution filtering matches these strings.
-- ═══════════════════════════════════════════════════════════════════════════
insert into pi_project_stakeholders
  (project_id, stakeholder_id, stakeholder_role, support, influence,
   distribution_groups, issue_tags, added_date, notes)
select p.id, s.id, v.role, v.support, v.influence, v.dist, v.tags, v.added::date, v.notes
from (values
  ('sr154','a-whitaker','Internal','Champion','High','Project team,Agency contacts','Schedule,Agency coordination','2024-03-04','UDOT Region 2 project manager and primary client contact. Wants the PI log current before every monthly progress meeting.'),
  ('sr154','a-okafor','Internal','Champion','High','Project team,Agency contacts','Construction,Traffic','2024-03-04','Resident Engineer. Coordinates lane closure windows and advance public notice.'),
