-- ═══════════════════════════════════════════════════════════════════════════
-- 10. INTERACTIONS — the last 26 weeks
--     Dated RELATIVE to the start of the current ISO week rather than to fixed
--     calendar dates, so the portal's "Engagement Activity — Last 8 Weeks" chart
--     is always full and the timeline never gaps, whenever the seed is run.
--     week_back 0 is the current (partial) week; least(..., current_date) keeps
--     it from placing anything in the future.
-- ═══════════════════════════════════════════════════════════════════════════
insert into pi_interactions
  (project_id, stakeholder_id, anon_label, nepa_stage, interaction_date, channel,
   subject, nature, direction, summary, logged_by, follow_up, follow_up_due,
   follow_up_note, follow_up_done)
select p.id, s.id, nullif(v.anon,''), v.stage,
       least(date_trunc('week', current_date)::date - v.week_back * 7 + v.dow,
             current_date),
       v.channel, v.subject, v.nature, v.direction, v.summary, v.logged_by, v.fu,
       case when v.fu then current_date - v.fu_due_ago else null end,
       nullif(v.fu_note,''), v.fu_done
from (values
