-- Discard the weeks that fall inside the fixed historical months above. On a
-- run soon after this file was written most of the deeper weeks are dropped;
-- run it months later and they materialise instead, so the two blocks always
-- meet without either a gap or a double-counted overlap.
where date_trunc('week', current_date)::date - v.week_back * 7 + v.dow
      > date '2026-01-31';


-- ═══════════════════════════════════════════════════════════════════════════
-- 10b. FOLLOW-UP ASSIGNMENT
--   Spreads half of the open follow-ups across the team so the Follow-ups view
--   demonstrates the "Assigned to me" / "I logged" split, and leaves the other
--   half unassigned so the COALESCE(follow_up_assigned_to, logged_by) fallback
--   is visible in the same list.
--
--   Guarded on the column existing, so this seed still runs cleanly against a
--   database where sql/2026-07-27_followup_assignment.sql has not been applied.
-- ═══════════════════════════════════════════════════════════════════════════
do $$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'pi_interactions'
                and column_name = 'follow_up_assigned_to') then
    execute $q$
      with tgt as (
        select i.id, i.logged_by, row_number() over (order by i.id) as rn
          from pi_interactions i
         where i.project_id::text in (select id::text from _seed_proj)
           and i.follow_up = true
           and coalesce(i.follow_up_done, false) = false
      )
      update pi_interactions x
         -- always hand it to somebody OTHER than the logger, so every assigned
         -- row is a real handoff and each of the three sees work arrive
         set follow_up_assigned_to = case tgt.logged_by
               when 'PUT' then case tgt.rn % 2 when 0 then 'SHA' else 'SAV' end
               when 'SHA' then case tgt.rn % 2 when 0 then 'SAV' else 'PUT' end
               else            case tgt.rn % 2 when 0 then 'PUT' else 'SHA' end
             end
        from tgt
       where x.id::text = tgt.id::text
         and tgt.rn % 2 = 0
    $q$;
    raise notice 'follow-up assignment: % of % open demo follow-up(s) handed to a teammate; the rest stay with whoever logged them.',
      (select count(*) from pi_interactions where follow_up_assigned_to is not null),
      (select count(*) from pi_interactions
        where follow_up = true and coalesce(follow_up_done,false) = false
          and project_id::text in (select id::text from _seed_proj));
  else
    raise notice 'follow-up assignment: column absent, skipped — run sql/2026-07-27_followup_assignment.sql to enable it.';
  end if;
end $$;

-- ═══════════════════════════════════════════════════════════════════════════
-- 11. COMMENT PERIOD + PUBLIC COMMENTS  (Project A)
--     pi_comment_periods and pi_public_comments use app-generated TEXT primary
--     keys (TEXT_PK_TABLES in index.html), so the ids are supplied here.
--
--     Oct 15 – Nov 15, 2025 is 31 days, which satisfies the EA 30-day minimum
--     in PERIOD_REQUIREMENTS. The optional EIS block at the bottom of this file
--     switches it to the 45-day DEIS requirement and extends the end date.
-- ═══════════════════════════════════════════════════════════════════════════
insert into pi_comment_periods
  (id, project_id, title, period_type, description, start_date, end_date, status)
select
  'cp-sr154-deis-2025', p.id,
  'DEIS Comment Period',
  'EA-30DAY',
  'Public review period on the draft environmental document for the SR-154 corridor. Notice of availability published in local and regional outlets; formal public hearing held October 22, 2025 with a court reporter present.',
  date '2025-10-15', date '2025-11-15', 'Closed'
from _seed_proj p where p.slug = 'sr154';

-- venue / hearing_date / first_ad_date are written by the desktop app but were
-- never migrated into the database (see
-- sql/2026-07-26_comment_periods_missing_columns.sql). Set them only if the
-- columns exist, so this seed runs correctly either before or after that
-- migration instead of failing with 42703.
do $$
declare
  vals constant jsonb := jsonb_build_object(
    'venue',         'Herriman High School, 11917 S Mustang Trail Way, Herriman',
    'hearing_date',  '2025-10-22',
    'first_ad_date', '2025-10-15');
  r record; applied text[] := '{}'; skipped text[] := '{}';
begin
  for r in
    select e.key as col,
           (select c.data_type from information_schema.columns c
             where c.table_schema = 'public' and c.table_name = 'pi_comment_periods'
               and c.column_name = e.key) as dtype
      from jsonb_each_text(vals) e
  loop
    if r.dtype is null then
      skipped := skipped || r.col;
    else
      -- cast through the column's real type; jsonb ->> yields text
      execute format('update pi_comment_periods set %I = $1::%s where id = $2', r.col, r.dtype)
        using (vals ->> r.col), 'cp-sr154-deis-2025';
      applied := applied || r.col;
    end if;
  end loop;
  if array_length(skipped, 1) > 0 then
    raise notice 'comment period: set [%]; skipped [%] — run sql/2026-07-26_comment_periods_missing_columns.sql to add them',
      array_to_string(applied, ', '), array_to_string(skipped, ', ');
  else
    raise notice 'comment period: all optional columns set (%).', array_to_string(applied, ', ');
  end if;
end $$;

