-- 12. CLIENT PORTAL ACCESS
--     Two paths, both wired up:
--       • Token share link  — pi_portal_links (no login)
--       • Magic-link login  — pi_client_access, granted by email
-- ═══════════════════════════════════════════════════════════════════════════
insert into pi_portal_links (token, project_id, label)
select 'a7f3c1d2-9e84-4b16-8f20-3c5d7e9a1b44'::uuid, id, 'UDOT Region 2 — demo share link'
from _seed_proj where slug = 'sr154';

insert into pi_portal_links (token, project_id, label)
select 'b2e5d8a4-1c73-4f92-a6d8-5b1e4c7f2a99'::uuid, id, 'Logan City — demo share link'
from _seed_proj where slug = 'logan';

-- Grant-by-email. user_id stays null until the client's first OTP login
-- self-provisions the auth user (see sql/2026-07-13_client_access_by_email.sql).
insert into pi_client_access (email, project_id)
select 'udot.demo@horizoncompass.com', id from _seed_proj where slug = 'sr154'
on conflict (email, project_id) do nothing;

insert into pi_client_access (email, project_id)
select 'logancity.demo@horizoncompass.com', id from _seed_proj where slug = 'logan'
on conflict (email, project_id) do nothing;

-- A third grant that sees BOTH projects — use this one to demo the portal's
-- multi-project selector.
insert into pi_client_access (email, project_id)
select 'demo@horizoncompass.com', id from _seed_proj
on conflict (email, project_id) do nothing;


-- ═══════════════════════════════════════════════════════════════════════════
-- 12b. SHARED PI REPORTS + PUBLISHED CLIENT TREND
--   Populates the portal's "Project Updates" tab — the leg of the client
--   portal no competitor has, which is otherwise empty until the consultant
--   archives and shares a report by hand.
--
--   Each snapshot matches _buildReportSnapshot() in index.html field for field,
--   including the inline-styled frozen tableHtml, so the portal renders these
--   exactly as it renders a report the desktop app archived. Doing this here
--   rather than by hand also means it SURVIVES a re-run of this seed, which
--   wipes pi_report_archive and pi_client_summaries for these two projects.
--
--   client_visible is false on SR-154 report #5 on purpose: the share toggle is
--   a real gate, and the demo should show one report held back.
-- ═══════════════════════════════════════════════════════════════════════════
insert into pi_report_archive
  (project_id, report_num, report_title, report_subtitle, period_start, period_end,
   overall_summary, sections, snapshot, client_visible, archived_at, archived_by)
select p.id, v.num, v.title, v.subtitle, v.pstart::date, v.pend::date,
       v.overall, v.snapshot::jsonb, v.snapshot::jsonb, v.visible, v.archived::timestamptz, 'J. Putzke'
from (values
  ('sr154',3,'PI Progress Report','SR-154 Corridor Safety Improvements — Monthly Public Involvement Summary','2026-04-01','2026-04-30','Corridor outreach held steady through April while the team worked the outstanding comment responses from the draft environmental document. The Harvest Hills noise wall request remains the most visible open item with the HOA board; the feasibility determination is pending and the board has been told to expect it in writing. Coordination with UDWR on the MP 14.2 crossing continues and is the one item that could affect the environmental schedule.','{"trendFacts": {}, "projName": "SR-154 Corridor Safety Improvements", "projPid": "25-154-001", "brand": "sunrise", "generatedAt": "2026-07-01T12:00:00.000Z", "periodLabel": "Apr 1, 2026 \u2013 Apr 30, 2026", "recipients": ["Marcus Whitaker", "Denise Okafor", "Tara Lindsey", "Alan Brekke", "Priya Raghavan", "Gordon Tuiasosopo", "Kim Delgado", "Nathan Pyper", "Carlos Mendive"], "includeInternal": false, "sections": [{"title": "Stakeholder Concerns & Coordination", "type": "auto-concerns", "summary": "Thirty-seven contacts were logged in April, weighted toward agency coordination and the two open corridor concerns. Noise remains the dominant resident theme along the Harvest Hills and Rosecrest frontage; no new concern categories emerged during the period.", "content": "", "showTable": true, "countsLabel": "30-day report period \u00b7 37 interactions in period", "tableHtml": "<table style=\"width:100%;border-collapse:collapse;margin-top:8px;table-layout:fixed\"><thead><tr><th style=\"padding:5px 8px;background:#1a3a5c;color:#fff;font-size:10px;text-transform:uppercase;letter-spacing:.4px;text-align:left;white-space:nowrap\">Date</th><th style=\"padding:5px 8px;background:#1a3a5c;color:#fff;font-size:10px;text-transform:uppercase;letter-spacing:.4px;text-align:left;white-space:nowrap\">Stakeholder</th><th style=\"padding:5px 8px;background:#1a3a5c;color:#fff;font-size:10px;text-transform:uppercas